<template><AsyncState :loading="loading" :error="error"><main class="page"><PageHeader :title="t('nav.isolate')"/><SectionCard :title="t('isolate.status')"><p>{{t('isolate.provider')}}: Docker {{status?.dockerAvailable?t('ai.available'):t('ai.unavailable')}}</p><p>{{t('isolate.active_mode')}}: {{status?.activeMode||t('isolate.mode_none')}}</p></SectionCard><SectionCard :title="t('isolate.setup')"><label>{{t('isolate.provider')}}<select v-model="mode" :disabled="operating"><option value="none">{{t('isolate.mode_none')}}</option><option value="container">{{t('isolate.mode_container')}}</option><option value="nix">{{t('isolate.mode_nix')}}</option></select></label><button class="xdev-btn xdev-btn--secondary" data-action="setup" :disabled="operating" @click="$emit('setup',mode)">{{t('isolate.setup_btn')}}</button><ConfirmAction :title="t('isolate.teardown_confirm')" :pending="operating" :confirm-label="t('isolate.teardown_btn')" :cancel-label="t('btn.cancel')" @confirm="$emit('teardown')"><template #trigger><button class="xdev-btn xdev-btn--secondary" data-action="teardown" :disabled="operating">{{t('isolate.teardown_btn')}}</button></template></ConfirmAction></SectionCard><SectionCard :title="t('isolate.exec')"><label>{{t('isolate.exec_placeholder')}}<input v-model.trim="command" data-field="isolate-command" :disabled="operating" @keyup.enter="run"></label><button class="xdev-btn xdev-btn--secondary" data-action="exec" :disabled="operating||!command" @click="run">{{t('btn.run')}}</button><CopyableValue v-if="output" :value="output" :max-length="120"/></SectionCard></main></AsyncState></template>
<script setup>import{ref,watch}from'vue';import AsyncState from'../components/AsyncState.vue';import ConfirmAction from'../components/ConfirmAction.vue';import CopyableValue from'../components/CopyableValue.vue';import PageHeader from'../components/PageHeader.vue';import SectionCard from'../components/SectionCard.vue';const props=defineProps({t:{type:Function,required:true},status:Object,loading:Boolean,error:[String,Error],output:String,operating:Boolean});const emit=defineEmits(['setup','exec','teardown']);const mode=ref(props.status?.activeMode||'none'),command=ref('');watch(()=>props.status?.activeMode,v=>{if(v)mode.value=v});const run=()=>command.value&&!props.operating&&emit('exec',command.value);</script><style scoped>.page{width:min(var(--xdev-reading-max-width),100%);margin:0 auto;display:grid;gap:var(--xdev-section-gap);min-width:0}label{display:grid;gap:var(--xdev-space-2)}</style>
